inline unsigned broadcastStandalone(const std::vector<one::Fixture>& fs){unsigned bad=0,index=0;auto cases=broadcastfixture::matrix(fs);
 for(bool custom:{true,false}){DiagnosticGraph g(custom?"broadcastStandalone":"broadcastStandard");std::array<unsigned,2> a,gate,y;for(unsigned h=0;h<2;++h){auto pr="h"+std::to_string(h);a[h]=g.tensor((pr+"a").c_str(),QNN_TENSOR_TYPE_APP_WRITE,{1,1,32,32});gate[h]=g.tensor((pr+"gate").c_str(),QNN_TENSOR_TYPE_APP_WRITE,{1,1,32,1});y[h]=g.tensor((pr+"y").c_str(),QNN_TENSOR_TYPE_APP_READ,{1,1,32,32});}
  unsigned receipt=0,last=0;if(custom){receipt=g.tensor("receipt",QNN_TENSOR_TYPE_APP_READ,{1,1,1,4168},QNN_DATATYPE_INT_32);g.node("broadcast","BroadcastMultiply","HexaFp32",{a[0],a[1],gate[0],gate[1]},{y[0],y[1],receipt});}else for(unsigned h=0;h<2;++h)g.node(("multiply"+std::to_string(h)).c_str(),QNN_OP_ELEMENT_WISE_MULTIPLY,"qti.aisw",{a[h],gate[h]},{y[h]});g.finalize();index=0;
  for(auto& z:cases){auto out=g.run({{a[0],z.a[0]},{a[1],z.a[1]},{gate[0],z.g[0]},{gate[1],z.g[1]}});if(custom){auto& r=out.at(receipt);if(r.size()!=4168||r[0]!=0x4838310au||r[1]<=last||r[2]!=2048||r[3]!=64||r[5]!=81||r[6]!=32){std::puts("BROADCAST_STANDALONE_RECEIPT_FAIL");return 3;}last=r[1];for(unsigned h=0;h<2;++h){for(unsigned j=0;j<1024;++j)if(r[8+h*1024+j]!=word(z.a[h][j])||r[2120+h*1024+j]!=out.at(y[h])[j])return 3;for(unsigned j=0;j<32;++j)if(r[2056+h*32+j]!=word(z.g[h][j]))return 3;}std::printf("broadcastperf,%u,math_us=%u,kernel_window_us=%u,graph_wall_us=%.3f\n",index,r[4],r[7],g.executeUs);}
   for(unsigned h=0;h<2;++h){auto ref=broadcastfixture::reference(z.a[h],z.g[h],false),fp=broadcastfixture::reference(z.a[h],z.g[h],true);auto actual=decode(out.at(y[h]));auto fail=metric(custom?"broadcastCustom":"broadcastStandard",index,"h"+std::to_string(h)+"_gate",ref,fp,actual,.01);unsigned lost=0;for(unsigned j=0;j<1024;++j)lost+=word(float(fp[j]))!=out.at(y[h])[j];if(custom)bad+=fail+(lost!=0);std::printf("broadcastcase,%s,%u,%u,fp_word_mismatch=%u\n",z.name.c_str(),index,h,lost);}++index;
  }
  if(!bad){auto& z=cases[0];for(unsigned rep=0;rep<9;++rep){auto o=g.run({{a[0],z.a[0]},{a[1],z.a[1]},{gate[0],z.g[0]},{gate[1],z.g[1]}});for(unsigned h=0;h<2;++h){auto expected=one::f(broadcastfixture::reference(z.a[h],z.g[h],true));if(custom&&decode(o[y[h]])!=expected)return 3;}std::printf("broadcaststeady,%u,%u,wall_us=%.3f,math_us=%u,kernel_window_us=%u\n",custom,rep,g.executeUs,custom?o[receipt][4]:0,custom?o[receipt][7]:0);}}
 }std::printf("broadcast_standalone_summary,cases=%zu,custom_failures=%u\n",cases.size(),bad);return bad;
}
inline unsigned broadcastFrontier(const std::vector<one::Fixture>& original){auto fs=upstreamreference::fullUpstream(original);auto bad=broadcastStandalone(fs);if(bad){std::printf("summary,oneBroadcast,standalone_failures=%u,integration_unexecuted=1\n",bad);return 4;}
 std::vector<std::map<std::string,one::FV>> anchors(fs.size());unsigned nextBad=0;
 for(unsigned phase=0;phase<4;++phase){bool next=phase>=2,tap=phase%2;std::string name=next?(tap?"broadcastNextTap":"broadcastNextNative"):(tap?"broadcastChainTap":"broadcastChainNative");OneGraph graph(name,tap,false,false,false,true,next);
  for(auto& z:fs){auto o=graph.g.run(graph.inputs(z));auto a=graph.audit(z,o);auto ref=one::reference(z),fp=one::reference(z,true);for(auto key:{"y","xhat","inverse","dx","dg","db","residual","dc","dw","h0_selected","h1_selected","h0_dc","h1_dc"})bad+=metric(name,z.index,key,ref.at(key),fp.at(key),a.at(key),limit(key));
   if(phase==0)anchors[z.index]=a;else for(auto key:{"y","dx","dc","dw","h0_selected","h1_selected","h0_dc","h1_dc"})if(a.at(key)!=anchors[z.index].at(key)){std::printf("BROADCAST_OBSERVER_FAIL,%s,%u\n",key,z.index);return 3;}
   if(next)for(unsigned h=0;h<2;++h){auto pr="h"+std::to_string(h)+"_";for(auto k:{"dp","dv"}){nextBad+=metric(name,z.index,pr+k,ref.at(pr+k),fp.at(pr+k),a.at(pr+k),.01);auto local=std::string(k)=="dp"?one::mm(one::d(a.at(pr+"dc")),one::d(z.v.at(pr+"v")),32,32,32,false,true):one::mm(one::d(z.v.at(pr+"p")),one::d(a.at(pr+"dc")),32,32,32,true,false);metric(name+"Local",z.index,pr+k,local,local,a.at(pr+k),.01);if(phase==2)anchors[z.index][pr+k]=a.at(pr+k);else if(anchors[z.index].at(pr+k)!=a.at(pr+k)){std::printf("NEXT_OBSERVER_FAIL,%s,%u\n",k,z.index);return 3;}}}
  }if(bad){std::printf("summary,oneBroadcast,segment_failures=%u\n",bad);return 4;}
  if(!next)for(unsigned rep=0;rep<9;++rep){auto o=graph.g.run(graph.inputs(fs[0]));graph.audit(fs[0],o);std::printf("broadcastchainsteady,%s,%u,wall_us=%.3f,math_us=%u,kernel_window_us=%u\n",name.c_str(),rep,graph.g.executeUs,o[graph.broadcastReceipt][4],o[graph.broadcastReceipt][7]);}
 }
 std::printf("summary,oneBroadcast,standalone_failures=0,segment_failures=0,next_consumer_failures=%u,cpu_fallback=0,input_mutation=0,finite=1,poison_remaining=0,canary_failures=0,training_updates=0\n",nextBad);return 0;
}
