 // Separate projection graphs expose the earliest measured upstream boundary,
 // preserving both native-input and native-output word receipts.
 for(auto field:{"q","k","v"}){std::string key=field;std::vector<one::FV> anchor(fs.size());
  for(unsigned mode=0;mode<3;++mode){DiagnosticGraph g("upstream_"+key+std::to_string(mode));auto x=g.tensor("ln1",QNN_TENSOR_TYPE_APP_WRITE,{1,1,32,64}),w=g.tensor("weight",QNN_TENSOR_TYPE_APP_WRITE,{1,1,64,64});unsigned mid=x,rin=0,rout=0,lastIn=0,lastOut=0;if(mode){mid=g.tensor("copied_ln1",mode==2?QNN_TENSOR_TYPE_APP_READ:QNN_TENSOR_TYPE_NATIVE,{1,1,32,64});rin=g.tensor("input_receipt",QNN_TENSOR_TYPE_APP_READ,{1,1,1,6152},QNN_DATATYPE_INT_32);g.node("input_copy","Copy","HexaFp32",{x},{mid,rin});}auto native=g.tensor("projection",QNN_TENSOR_TYPE_NATIVE,{1,1,32,64});op::mm(g,"projection_mm",mid,w,native);auto y=g.tensor("readback",QNN_TENSOR_TYPE_APP_READ,{1,1,32,64});rout=g.tensor("output_receipt",QNN_TENSOR_TYPE_APP_READ,{1,1,1,6152},QNN_DATATYPE_INT_32);g.node("output_copy","Copy","HexaFp32",{native},{y,rout});g.finalize();
   for(auto& z:fs){auto o=g.run({{x,z.v.at("ln1")},{w,z.v.at("w"+key)}});auto a=decode(o[y]);if(rin){std::vector<uint32_t> bits;for(auto v:z.v.at("ln1"))bits.push_back(word(v));copyReceipt(o[rin],z.v.at("ln1"),bits,lastIn);if(mode==2&&o[mid]!=bits)return 3;}copyReceipt(o[rout],a,o[y],lastOut);auto ref=one::mm(one::d(z.v.at("ln1")),one::d(z.v.at("w"+key)),32,64,64),fp=one::mm(one::d(z.v.at("ln1")),one::d(z.v.at("w"+key)),32,64,64,false,false,true);metric("upstreamProjection"+std::to_string(mode),z.index,key,ref,fp,a,.002);unsigned lost=0;for(unsigned j=0;j<2048;++j)lost+=word(float(fp[j]))!=o[y][j];std::printf("upstreamwords,%s,%u,%u,lost=%u\n",key.c_str(),z.index,mode,lost);if(mode==0)anchor[z.index]=a;else if(anchor[z.index]!=a){std::puts("UPSTREAM_PROJECTION_OBSERVER_FAIL");return 3;}}
  }
 }
